## 核心设计：交易平台抽象层（支持 MT4/MT5）

### ITradingPlatform 接口

为支持未来 MT4 接入，设计统一的交易平台抽象接口：

```cpp
// include/services/ITradingPlatform.h

#pragma once
#include <string>
#include <vector>
#include <optional>
#include <json/json.h>

namespace services {

// 平台类型枚举
enum class PlatformType {
    MT5,
    MT4,
    UNKNOWN
};

// 通用用户信息结构
struct TradingUser {
    uint64_t login;
    std::string name;
    std::string group;
    std::string email;
    std::string phone;
    uint32_t leverage;
    double balance;
    double equity;
    double margin;
    double marginFree;
    bool isEnabled;
    int64_t registrationTime;
    int64_t lastAccessTime;

    Json::Value toJson() const;
};

// 通用组信息结构
struct TradingGroup {
    std::string name;
    std::string description;
    uint32_t leverage;
    std::string currency;

    Json::Value toJson() const;
};

// 通用持仓信息结构
struct TradingPosition {
    uint64_t ticket;
    std::string symbol;
    std::string action;  // "buy" or "sell"
    double volume;
    double openPrice;
    double currentPrice;
    double profit;
    double sl;
    double tp;
    int64_t openTime;

    Json::Value toJson() const;
};

// 交易平台抽象接口
class ITradingPlatform {
public:
    virtual ~ITradingPlatform() = default;

    // 平台标识
    virtual PlatformType getPlatformType() const = 0;
    virtual std::string getPlatformName() const = 0;

    // 连接管理
    virtual bool connect(const std::string& server, uint64_t login,
                         const std::string& password, int timeout = 10000) = 0;
    virtual void disconnect() = 0;
    virtual bool isConnected() const = 0;

    // 用户管理
    virtual std::optional<TradingUser> getUser(uint64_t login) = 0;
    virtual std::vector<TradingUser> getUserList(const std::string& group = "",
                                                  int page = 1, int limit = 20,
                                                  const std::string& keyword = "") = 0;
    virtual int getUserTotal(const std::string& group = "") = 0;

    // 组管理
    virtual std::vector<TradingGroup> getGroupList() = 0;
    virtual bool groupExists(const std::string& groupName) = 0;

    // 用户修改
    virtual bool updateUserGroup(uint64_t login, const std::string& newGroup) = 0;
    virtual bool updateUserLeverage(uint64_t login, uint32_t leverage) = 0;
    virtual bool updateUserStatus(uint64_t login, bool enabled) = 0;

    // 持仓和历史
    virtual std::vector<TradingPosition> getUserPositions(uint64_t login) = 0;
    virtual Json::Value getUserHistory(uint64_t login, int64_t from, int64_t to,
                                       int page = 1, int limit = 20) = 0;

    // 用户认证
    virtual bool authenticateUser(uint64_t login, const std::string& password) = 0;
};

// 平台工厂
class TradingPlatformFactory {
public:
    static std::unique_ptr<ITradingPlatform> create(PlatformType type);
};

} // namespace services
```

### MT5Manager 实现接口

```cpp
// MT5Manager 继承 ITradingPlatform
class MT5Manager : public ITradingPlatform {
public:
    // ITradingPlatform 接口实现
    PlatformType getPlatformType() const override { return PlatformType::MT5; }
    std::string getPlatformName() const override { return "MetaTrader 5"; }

    // ... 现有方法适配到接口
};
```

