### Component 2: ManagerSessionPool（增强版）

**Purpose:** 多租户连接池管理，支持 `tenant_id:server_id` 粒度隔离

**File:** `include/services/ManagerSessionPool.h` (修改现有)

**关键修改：**

```cpp
// 连接池 Key 格式
struct PoolKey {
    std::string tenantId;
    std::string serverId;

    std::string toString() const { return tenantId + ":" + serverId; }

    bool operator==(const PoolKey& other) const {
        return tenantId == other.tenantId && serverId == other.serverId;
    }
};

// 为 PoolKey 提供 hash
struct PoolKeyHash {
    size_t operator()(const PoolKey& key) const {
        return std::hash<std::string>()(key.toString());
    }
};

class ManagerSessionPool {
public:
    // 新增：根据租户和服务器获取连接
    std::shared_ptr<ITradingPlatform> getConnection(
        const std::string& tenantId,
        const std::string& serverId
    );

    // 新增：带熔断器保护的执行
    template<typename Func>
    auto executeWithCircuitBreaker(
        const std::string& tenantId,
        const std::string& serverId,
        Func&& func
    ) -> std::optional<decltype(func())>;

    // 新增：健康状态查询
    ServerHealthInfo getServerHealth(const std::string& tenantId,
                                      const std::string& serverId);
    Json::Value getAllServerHealth();

    // 新增：动态租户管理
    bool addTenantServer(const std::string& tenantId, const ServerConfig& config);
    bool removeTenantServer(const std::string& tenantId, const std::string& serverId);

private:
    // 修改：使用 PoolKey 作为 Key
    std::unordered_map<PoolKey, std::unique_ptr<ITradingPlatform>, PoolKeyHash> m_connections;
    std::unordered_map<PoolKey, std::unique_ptr<CircuitBreaker>, PoolKeyHash> m_circuitBreakers;
    std::unordered_map<PoolKey, ServerHealthInfo, PoolKeyHash> m_healthInfo;

    // 租户配置管理器
    std::shared_ptr<TenantConfigManager> m_tenantConfig;
};
```

